#include <bits/stdc++.h>
using namespace std;

void deleteNode(ListNode* node) {
    node->val = node->next->val;                                                 // impersonate the next node by copying its value in
    node->next = node->next->next;                                                // then bypass that now-duplicated next node entirely
}

int main() {
    ListNode* n4 = new ListNode(9);
    ListNode* n3 = new ListNode(1, n4);
    ListNode* n2 = new ListNode(5, n3);
    ListNode* n1 = new ListNode(4, n2);
    deleteNode(n2);
    ListNode* node = n1;
    while (node) { cout << node->val << " "; node = node->next; }
    cout << endl;
    return 0;
}
